// === Tab: mySketch ===
bgCircle bgC;
let OneCircle;
let version = int(random(0, 100));

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	createCanvas(width, height);
	// pixelDensity(2);
	colorMode(HSB, 360, 100, 100, 1.0);
	if (version % 2 == 0) {
		background(0, 0, 95);
	}
	if (version % 2 == 1) {
		background(0, 0, 5);
	}
	bgC = new bgCircle(width / 2, height / 2);
	OneCircle = new CircleGroup();
}

function draw() {
	// background(0, 0, 95); 
	noStroke();
	OneCircle.addCircles();
	OneCircle.run();

}


class CircleGroup {
	ArrayList < circle > circleG;
	ArrayList < circle > circles;
	x, y;

	constructor() {
		circleG = new ArrayList < circle > ();
		circles = new ArrayList < circle > ();
	}

	function addCircles() {
		circleG.add(new circle(x, y));
	}


	function run() {

		let total = 5;
		let count = 0;
		let attempts = 0;

		while (count < total) {
			circle newC = newCircle();
			for (i = 0; i < 1; i++) {
				circle a = circleG.get(i);
				a.display();
				if (a.isDead()) {
					circleG.remove(i);
				}
			}
			if (newC != null) {
				circles.add(newC);
				count++;
			}
			attempts++;
			if (attempts > 50) {
				noLoop();
			}
		}

		for (circle c: circles) {
			if (c.growing) {
				if (c.edges()) {
					c.growing = false;
				} else {
					for (circle other: circles) {
						if (c != other) {
							let d = dist(c.xpos, c.ypos, other.xpos, other.ypos);
							if (d < c.r + other.r) {
								c.growing = false;
								// break;
							}
						}
					}
				}
			}
			c.display();
			c.grow();
		}
	}

	circle newCircle() {

		let x = random((bgC.x - bgC.r), (bgC.x + bgC.r));
		let y = random((bgC.y - bgC.r), (bgC.y + bgC.r));

		let valid = true;
		for (circle c: circles) {
			let d1 = dist(x, y, bgC.x, bgC.y);
			let d2 = dist(x, y, c.xpos, c.ypos);
			if (d1 - 2 * c.r > bgC.r || d2 < c.r) {
				valid = false;
			}
		}

		if (valid) {
			return new circle(x, y);
		} else {
			return null;
		}
	}
}

class bgCircle {

	x, y;
	r;

	constructor(x_, y_) {
		x = x_;
		y = y_;
		r = max(width, height) / 3;
	}

	function display() {
		noStroke();
		fill(0, 0, 100, 1);
		ellipse(x, y, r * 2, r * 2);
	}
}

function keyPressed() {
		save("0316_the Voise of Group_2022.png");
}

// === Tab: class_circle ===
class circle {
	xpos, ypos;
	plusA, plusB, plusC, plusD;
	r, trans;
	colA, colB, colC;
	Num, weight;
	growing = true;


	constructor(x_, y_) {
		xpos = x_;
		ypos = y_;
		Num = int(random(0, 100));
		r = 0;
		plusC = random(1, 3);
		plusA = random(0.5, 0.75);
		plusB = random(0.2, 0.5);
		plusD = random(0.05, 0.1);

		if (version % 3 == 0) {
			colA = color(190, 80, 80, 0.05);
			colB = color(10, 70, 90, 0.05);
			colC = color(0, 0, 95, 0.05);
		}
		if (version % 3 == 1) {
			colA = color(80, 70, 90, random(0.025, 0.04));
			colB = color(270, 70, 90, random(0.025, 0.04));
			colC = color(0, 0, 95, 0.08);
		}
		if (version % 3 == 2) {
			colA = color(53, 65, 95, random(0.1, 0.15));
			colB = color(165, 45, 90, random(0.05, 0.1));
			colC = color(0, 0, 95, 0.5);
		}

		trans = random(0.05, 0.1);
	}

	function grow() {
		if (growing) {
			if (r >= 0 && r < 5) {
				r += plusC;
			} else if (r >= 5 && r < 12) {
				r += plusA;
			} else if (r >= 12 && r < 20) {
				r += plusB;
			} else if (r >= 20 && r < 100) {
				r += plusD;
			}
		}
	}

	function disapear() {
		if (r > 150) {
			trans -= 0.01;
		}
	}

	function update() {
		xpos += random(-1, 1);
		ypos += random(-1, 1);
	}

	function display() {

		if (version % 2 == 0) {
			noStroke();

			if (Num % 7 == 0) {
				fill(colB);
			} else if (Num % 7 == 1 || Num % 7 == 2) {
				fill(colC);
			} else {
				fill(colA);
			}
		}
		if (version % 2 == 1) {
			noFill();
      strokeWeight(random(2));
			if (Num % 7 == 0) {
				stroke(colB);
			} else if (Num % 7 == 1 || Num % 7 == 2) {
				stroke(colC);
			} else {
				stroke(colA);
			}
		}

		ellipse(xpos, ypos, r * 2, r * 2);
		this.update();
		this.disapear();
	}

	isDead() {
		if (trans < 0.02) {
			return true;
		} else {
			return false;
		}
	}
	edges() {
		return (xpos + r > width || xpos - r < 0 || ypos + r > height || ypos - r < 0);
	}
}

